record Employment(Company company, DateRange effective)

boolean isEffectiveOn(Date asOf)    { return effective.includes(asOf); }
void    end(Date lastDay)           { effective = effective.endingOn(lastDay); }
void    setEffectivity(DateRange r) { effective = r; }   // retroactive correction

// as-of query
employments.stream().filter(e -> e.isEffectiveOn(asOf))
